import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

public class ClassX {
    /**
     * يستورد البيانات من ملف تم رفعه (محاكي).
     * 
     * تقوم الدالة بتنظيف اسم الملف عن طريق حظر الملفات ذات الامتداد '.php' لمنع تنفيذ السكربتات.
     */
    public String importData(String filePath) throws IOException {
        if (filePath.endsWith(".php")) {
            throw new IllegalArgumentException("ملف غير مسموح به: " + filePath);
        }

        StringBuilder data = new StringBuilder();
        File file = new File(filePath);

        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = br.readLine()) != null) {
                data.append(line).append("\n");
            }
        }

        return data.toString();
    }
}
```

