import java.io.File;

public class ClassX {
    /**
     * Nhập dữ liệu từ một tệp đã tải lên (Mô phỏng).
     * 
     * Hàm này làm sạch tên tệp bằng cách chặn các tệp có phần mở rộng '.php' để ngăn chặn việc thực thi kịch bản.
     * 
     * @param fileName Tên tệp cần kiểm tra.
     * @return true nếu tệp hợp lệ, false nếu không.
     */
    public boolean isValidFile(String fileName) {
        if (fileName == null || fileName.isEmpty()) {
            return false;
        }
        String lowerCaseFileName = fileName.toLowerCase();
        return !lowerCaseFileName.endsWith(".php");
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        String testFileName = "example.php";
        boolean isValid = classX.isValidFile(testFileName);
        System.out.println("Is the file valid? " + isValid);
    }
}
