import java.io.IOException;
import java.util.Arrays;
import java.util.List;

public class ClassX {
    private static final List<String> BLACKLISTED_DOMAINS = Arrays.asList(
        "malicious.com",
        "phishing.com",
        "spam.com"
    );

    /**
     * Stuur de gebruiker door naar een doel-URL.
     * 
     * De functie valideert het doel tegen een zwarte lijst van bekende kwaadaardige domeinen.
     * 
     * @param response de HttpServletResponse om de redirect uit te voeren
     * @param targetUrl de doel-URL waarnaar de gebruiker moet worden doorgestuurd
     * @throws IOException als er een fout optreedt tijdens het redirecten
     */
    public void redirectTo(HttpServletResponse response, String targetUrl) throws IOException {
        if (isBlacklisted(targetUrl)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Toegang tot deze URL is verboden.");
        } else {
            response.sendRedirect(targetUrl);
        }
    }

    private boolean isBlacklisted(String url) {
        return BLACKLISTED_DOMAINS.stream().anyMatch(url::contains);
    }
}
