import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;

public class ClassX {
    /**
     * Kumuha ng nilalaman mula sa isang nabuo na URL pagkatapos i-validate ang host.
     * 
     * Ang function na ito ay naglilinis ng host sa pamamagitan ng pag-check para sa mga hindi wastong karakter tulad ng mga espasyo.
     */
    public String fetchContent(String urlString) throws Exception {
        if (!isValidHost(urlString)) {
            throw new MalformedURLException("Invalid URL host.");
        }

        StringBuilder content = new StringBuilder();
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        try (BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
        }

        return content.toString();
    }

    private boolean isValidHost(String urlString) {
        String host = urlString.replaceAll("^(https?://)?(www\\.)?", "").split("/")[0];
        return !host.contains(" ") && !host.isEmpty();
    }
}
