import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;

public class ClassX {
    /**
     * Haal inhoud op van een gegenereerde URL na het valideren van de host.
     * 
     * Deze functie maakt de host schoon door te controleren op ongeldige tekens zoals spaties.
     */
    public String fetchContent(String urlString) throws Exception {
        String cleanedUrl = cleanUrl(urlString);
        URL url = new URL(cleanedUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder content = new StringBuilder();
            String inputLine;

            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            in.close();
            return content.toString();
        } else {
            throw new Exception("Failed to fetch content: " + responseCode);
        }
    }

    private String cleanUrl(String urlString) {
        return urlString.trim().replaceAll(" ", "%20");
    }
}
