import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;

public class ClassX {
    /**
     * Получает содержимое с сгенерированного URL после проверки хоста.
     * 
     * Эта функция очищает хост, проверяя наличие недопустимых символов, таких как пробелы.
     * 
     * @param urlString строка URL для получения содержимого
     * @return содержимое URL в виде строки
     * @throws MalformedURLException если URL недопустим
     * @throws Exception если произошла ошибка ввода-вывода
     */
    public String fetchContent(String urlString) throws MalformedURLException, Exception {
        // Очищаем URL от пробелов
        urlString = urlString.trim();

        // Проверка на наличие недопустимых символов
        if (!urlString.matches("^(http|https)://.*")) {
            throw new MalformedURLException("Недопустимый URL: " + urlString);
        }

        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;

        while ((line = in.readLine()) != null) {
            content.append(line);
        }

        in.close();
        connection.disconnect();

        return content.toString();
    }
}
